#!/usr/bin/env bash
# Question 1: New Pods rejected in batch. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "batch" >/dev/null 2>&1 || kubectl get namespace "batch" >/dev/null
timeout 60 bash -c "until kubectl -n 'batch' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: worker
  namespace: batch
  labels: { app: worker }
spec:
  replicas: 0
  selector:
    matchLabels: { app: worker }
  template:
    metadata:
      labels: { app: worker }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          resources:
            requests: { cpu: 100m, memory: 64Mi }
EOF

case "${Q1_FAULT}" in
  quota-pods)
    kubectl -n "batch" apply -f - <<< '{"apiVersion":"v1","kind":"ResourceQuota","metadata":{"name":"tenant-quota"},"spec":{"hard":{"pods":"1"}}}'
    ;;
  quota-limits)
    kubectl -n "batch" apply -f - <<< '{"apiVersion":"v1","kind":"ResourceQuota","metadata":{"name":"compute-quota"},"spec":{"hard":{"requests.cpu":"2","limits.cpu":"4"}}}'
    ;;
  limitrange-max)
    kubectl -n "batch" apply -f - <<< '{"apiVersion":"v1","kind":"LimitRange","metadata":{"name":"container-limits"},"spec":{"limits":[{"type":"Container","max":{"cpu":"50m"}}]}}'
    ;;
  limitrange-min)
    kubectl -n "batch" apply -f - <<< '{"apiVersion":"v1","kind":"LimitRange","metadata":{"name":"container-floor"},"spec":{"limits":[{"type":"Container","min":{"memory":"128Mi"}}]}}'
    ;;
  pod-security)
    kubectl label namespace "batch" pod-security.kubernetes.io/enforce=restricted --overwrite
    ;;
  webhook)
    kubectl label namespace "batch" policy.cka.lab/checked=true --overwrite
    kubectl apply -f - <<< '{"apiVersion":"admissionregistration.k8s.io/v1","kind":"ValidatingWebhookConfiguration","metadata":{"name":"'"batch"'-pod-policy"},"webhooks":[{"name":"pods.policy.cka.lab","failurePolicy":"Fail","sideEffects":"None","timeoutSeconds":3,"admissionReviewVersions":["v1"],"clientConfig":{"service":{"name":"pod-policy","namespace":"'"batch"'","path":"/validate"},"caBundle":"LS0tLS0tRU5EIENFUlRJRklDQVRFLS0tLS0t"},"rules":[{"apiGroups":[""],"apiVersions":["v1"],"operations":["CREATE"],"resources":["pods"],"scope":"Namespaced"}],"namespaceSelector":{"matchLabels":{"policy.cka.lab/checked":"true"}}}]}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "batch" scale "deployment/worker" --replicas=2
# What "do not change the Deployment" means: this object, replica count and Pod spec. A rollout
# restart only annotates the template, so it stays allowed.
kubectl -n "batch" get deployment "worker" -o jsonpath='{.metadata.uid} {.spec.replicas} {.spec.template.spec}' > "/var/tmp/cka-q1.deploy"
chmod 644 "/var/tmp/cka-q1.deploy"
sleep 15
[[ "$(kubectl -n "batch" get deployment "worker" -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "worker still runs 2 replicas" >&2; exit 1; }
